import type { Metadata } from "next";
import { site } from "@/content/site";

/** The share card generated by app/opengraph-image.tsx. */
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: site.title };

/**
 * Metadata for an inner page. Next merges metadata shallowly, so a page that sets only a title
 * would inherit the homepage's canonical URL and OpenGraph block. This sets all three per page.
 * Setting `openGraph` replaces the layout's block entirely, which also drops the root share
 * image, so it is passed back in explicitly.
 * The title runs through the root layout's template ("About us — Run the Reach").
 */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const full = `${title} — ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: "website", title: full, description, siteName: site.name, url: path, images: [shareImage] },
    twitter: { card: "summary_large_image", title: full, description, images: [shareImage] },
  };
}
